#!/usr/bin/env node

import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");

const PROSE = new Set(["Markdown", "Text", "Plain Text"]);

const GENERATED = [
  "graphify-out",
  "app/linux/flutter",
  "app/windows/flutter",
  "app/macos/Flutter/GeneratedPluginRegistrant.swift",
  "desktop/permissions/autogenerated",
];

const FUNCTIONAL = [
  /^#!/,
  /^# syntax=/,
  /^<!--DDD_[A-Z_]+-->$/,
  /^\/\/\/ <reference /,
  /^\/\/ @ts-expect-error\b/,
  /^\/\/ eslint-disable/,
  /^\/\* eslint-disable[^*]*\*\/$/,
  /^\/\/ prettier-ignore$/,
  /^\/\* @vite-ignore \*\/$/,
  /^\/\/ ignore(_for_file)?: /,
];

function tokei() {
  const excludes = GENERATED.flatMap((path) => ["--exclude", path]);
  const run = spawnSync("tokei", [".", "--files", "--output", "json", ...excludes], {
    cwd: root,
    encoding: "utf8",
    maxBuffer: 256 * 1024 * 1024,
  });
  if (run.error) {
    console.error(`could not run tokei: ${run.error.message}`);
    process.exit(2);
  }
  if (run.status !== 0) {
    console.error(run.stderr);
    process.exit(2);
  }
  return JSON.parse(run.stdout);
}

function commentLines(stats) {
  let total = stats.comments;
  for (const blob of Object.values(stats.blobs ?? {})) total += commentLines(blob);
  return total;
}

function functionalLines(path) {
  return readFileSync(join(root, path), "utf8")
    .split("\n")
    .filter((line) => FUNCTIONAL.some((pattern) => pattern.test(line.trim()))).length;
}

const offenders = [];
for (const [language, summary] of Object.entries(tokei())) {
  if (language === "Total" || PROSE.has(language)) continue;
  for (const report of summary.reports ?? []) {
    const comments = commentLines(report.stats);
    if (comments === 0) continue;
    const path = relative(root, resolve(root, report.name));
    const extra = comments - functionalLines(path);
    if (extra > 0) offenders.push({ path, language, extra });
  }
}

if (offenders.length > 0) {
  offenders.sort((a, b) => a.path.localeCompare(b.path));
  console.error("Comments or docstrings found. Explain through naming, or in the directory's README:");
  for (const { path, language, extra } of offenders) {
    console.error(`  ${path} (${language}): ${String(extra)} comment line${extra === 1 ? "" : "s"}`);
  }
  process.exit(1);
}
console.log("no comments or docstrings");
